import heapq


def find_minimum_range(list):
    """Write a function to find the smallest range that includes at-least one element from each of the given arrays."""
    if not list:
        raise ValueError("input must contain at least one array")
    sorted_lists = []
    for arr in list:
        if not arr:
            raise ValueError("each array must be non-empty")
        sorted_lists.append(sorted(arr))
    heap = []
    current_max = sorted_lists[0][0]
    for i, arr in enumerate(sorted_lists):
        val = arr[0]
        heap.append((val, i, 0))
        if val > current_max:
            current_max = val
    heapq.heapify(heap)
    best_min = heap[0][0]
    best_max = current_max
    best_len = best_max - best_min
    if best_len == 0:
        return (best_min, best_max)
    while heap:
        min_val, list_idx, elem_idx = heapq.heappop(heap)
        cur_len = current_max - min_val
        if cur_len < best_len:
            best_len = cur_len
            best_min, best_max = min_val, current_max
            if best_len == 0:
                break
        if elem_idx + 1 >= len(sorted_lists[list_idx]):
            break
        next_val = sorted_lists[list_idx][elem_idx + 1]
        heapq.heappush(heap, (next_val, list_idx, elem_idx + 1))
        if next_val > current_max:
            current_max = next_val
    return (best_min, best_max)
